/*
 * ASK WHEN THE PAGE SAYS WHICH LESSON (TASK-L171 §0b). The fixture was one
 * lesson and needed no argument; the backend holds one per concept, so the page
 * passes the concept it was opened for (its `concept` query parameter) and this
 * asks for exactly that. Nothing arrives, nothing is asked: a lesson page opened
 * with no concept names no lesson, and guessing one would be a lesson somebody
 * did not open.
 */
const concept = String(Inputs.conceptId || '');
if (!concept) return;
Outputs.conceptId = concept;
Outputs.ask();

/*
 * A REFUSAL IS NO LESSON (TASK-L171). Signed out, the App gate sends the page
 * to sign-in before this could matter; if the call fails anyway, the page gets
 * the same empty answer a lesson not written yet gets, not a spinner.
 */
Outputs.items = [];

function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
/*
 * THE SAME SPLIT THE FIXTURE HAD (Data/Specimen lesson's fx_split), with ONE
 * difference, and it is the reason `found` exists: the fixture could not be
 * empty, and a backend can. Sam's next step has no lesson written for it yet
 * (sprint 49 decision 7), so an empty answer must reach the page as a state it
 * can draw — "not written yet" — rather than as silence. So on an empty answer
 * every part is emptied (a page that showed one lesson must not keep drawing it
 * under another's name) and `found` is false; `loaded` fires either way.
 */
const rows = plain(Inputs.items) || [];
const lesson = rows[0];
if (!lesson) {
  Outputs.title = '';
  Outputs.hook = '';
  Outputs.landing = '';
  Outputs.conceptId = '';
  Outputs.steps = [];
  Outputs.sections = [];
  Outputs.found = false;
  Outputs.loaded();
  return;
}
Outputs.title = lesson.title || '';
Outputs.hook = lesson.hook || '';
Outputs.landing = lesson.landing || '';
Outputs.conceptId = lesson.conceptId || '';
Outputs.steps = lesson.steps || [];
Outputs.sections = lesson.sections || [];
Outputs.found = true;
Outputs.loaded();
